impl Solution {
    pub fn num_distinct(s: String, t: String) -> i32 {
        let s = s.as_bytes();
        let t = t.as_bytes();
        let m = s.len();
        let n = t.len();
        if n > m {
            return 0;
        }
        let mut dp = vec![vec![-1i32; n + 1]; m + 1];

        fn dfs(s: &[u8], t: &[u8], i: usize, j: usize, dp: &mut Vec<Vec<i32>>) -> i32 {
            if j == t.len() {
                return 1;
            }
            if i == s.len() {
                return 0;
            }
            if dp[i][j] != -1 {
                return dp[i][j];
            }
            let mut res = dfs(s, t, i + 1, j, dp);
            if s[i] == t[j] {
                res += dfs(s, t, i + 1, j + 1, dp);
            }
            dp[i][j] = res;
            res
        }

        dfs(s, t, 0, 0, &mut dp)
    }
}
